-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1d721207-fc75-5e2b-af39-92bfc3b44881'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'explanation_exceptions', 'unser, euer and ihr / Ihr', 'unser, euer und ihr / Ihr', '{"type":"case_table","headers":["Fall","unser","euer","ihr / Ihr"],"rows":[["Nominativ maskulin","unser Vater","euer Vater","ihr Vater / Ihr Vater"],["Nominativ feminin","unsere Mutter","eure Mutter","ihre Mutter / Ihre Mutter"],["Akkusativ maskulin","unseren Vater","euren Vater","ihren Vater / Ihren Vater"],["Dativ maskulin/neutrum","unserem Kind","eurem Kind","ihrem Kind / Ihrem Kind"],["Dativ feminin","unserer Mutter","eurer Mutter","ihrer Mutter / Ihrer Mutter"],["Dativ Plural","unseren Kindern","euren Kindern","ihren Kindern / Ihren Kindern"]],"highlight_row":-1,"description_de":"euer verliert ein -e-: euer, aber eure, euren, eurem. unser behält es immer.","description_en":"euer drops the -e- in the middle as soon as an ending is added: euer -> eure, euren, eurem. unser keeps it: unsere, unseren, unserem. Small ihr means her or their; capital Ihr is always the polite your (Sie-form)."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'euer + ending = eure. One e falls out.', 'euer + Endung = eure. Ein e fällt weg.', 'In letters and e-mails the polite Ihr always keeps its capital I: Ihr Brief, Ihre Adresse, Ihrem Kollegen.', 'In Briefen und E-Mails schreibst du Ihr immer groß: Ihr Brief, Ihre Adresse.', 'Small ihr = her or their. Capital Ihr = your (Sie-form). Only the capital letter tells them apart.', 'Kleines ihr heißt: von ihr oder von ihnen. Großes Ihr gehört immer zu Sie.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1d721207-fc75-5e2b-af39-92bfc3b44881'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '593fc302-3d59-57b6-92e2-456a09f4ab06'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'explanation_patterns', 'Possessives after dative prepositions', 'Possessivpronomen nach Dativ-Präpositionen', '{"type":"case_table","headers":["Präposition","Beispiel","Form"],"rows":[["mit","Ich fahre mit meinem Chef zur Arbeit.","maskulin: meinem"],["bei","Sie arbeitet bei ihrer Tante.","feminin: ihrer"],["zu","Wir gehen zu unserem Zahnarzt.","maskulin: unserem"],["von","Das Paket kommt von meiner Chefin.","feminin: meiner"],["nach","Nach eurem Termin trinken wir Kaffee.","maskulin: eurem"],["aus","Der Brief kommt aus seiner Firma.","feminin: seiner"],["mit (Plural)","Ich spiele Karten mit meinen Großeltern.","Plural: meinen"]],"highlight_row":-1,"description_de":"Nach mit, bei, zu, von, nach und aus steht immer der Dativ. Dein Possessivpronomen bekommt dann auch eine Dativ-Endung.","description_en":"After mit, bei, zu, von, nach and aus the dative is compulsory, and the possessive carries the dative ending too. The same happens after the dative verbs helfen, danken, gehören, gefallen and passen: Ich helfe meiner Nachbarin."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'mit, bei, zu -> always dative. Think -em, -er, -en.', 'mit, bei, zu: immer Dativ. Denk an -em, -er, -en.', NULL, NULL, 'The dative endings are identical on every possessive: -em (masc./neut.), -er (fem.), -en (plural). In the plural the noun adds -n as well: meinen Kindern.', 'Dativ-Endungen: -em (maskulin/neutrum), -er (feminin), -en (Plural).'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '593fc302-3d59-57b6-92e2-456a09f4ab06'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '35e488b1-1325-5ee4-87a6-3735dfa9b383'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'common_mistakes', 'Mistakes with possessives', 'Fehler mit Possessivpronomen', '{"intro_de":"Diese Fehler hörst du oft. Achte besonders auf den Dativ.","intro_en":"These five slips turn up in almost every A2 writing task. Check the case first, the gender second.","mistakes":[{"wrong":"Das Auto gehört unsere Nachbarin.","correct":"Das Auto gehört unserer Nachbarin.","explanation_de":"gehören braucht den Dativ. Feminin heißt es unserer.","explanation_en":"gehören is a dative verb, and the feminine dative ending is -er: unserer Nachbarin.","memory_trick_en":"Feminine dative -er, like der Nachbarin."},{"wrong":"Wann kommen euere Gäste?","correct":"Wann kommen eure Gäste?","explanation_de":"euer verliert vor der Endung ein e.","explanation_en":"euer loses the e in the middle before an ending: eure, never euere."},{"wrong":"Ich frage seine Chef.","correct":"Ich frage seinen Chef.","explanation_de":"Chef ist maskulin und Akkusativ: seinen.","explanation_en":"Chef is masculine and the direct object, so sein becomes seinen."},{"wrong":"Das ist Ihre Formular, Frau Sommer.","correct":"Das ist Ihr Formular, Frau Sommer.","explanation_de":"Formular ist neutrum. Im Nominativ steht Ihr ohne Endung.","explanation_en":"Formular is neuter nominative, so the possessive takes no ending at all."},{"wrong":"Er fährt mit seine Freunde nach Wien.","correct":"Er fährt mit seinen Freunden nach Wien.","explanation_de":"Im Plural heißt es seinen Freunden, mit -n am Nomen.","explanation_en":"mit takes the dative: the possessive ends in -en and the noun adds -n."}]}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Ask the case first, the gender second. Then the ending is easy.', 'Frag zuerst nach dem Fall, dann nach dem Geschlecht.', NULL, NULL, 'Nearly every possessive error is a case error, not a gender error.', 'Viele Fehler sind Fehler beim Fall, nicht beim Geschlecht.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '35e488b1-1325-5ee4-87a6-3735dfa9b383'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1bf98739-369e-53c1-b847-661315030301'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'explanation_patterns', 'Where does the ge- go?', 'Wo steht das ge-?', '{"type":"case_table","headers":["Verbtyp","Test","Partizip","Beispiel"],"rows":[["Verb auf -ieren","Endung -ieren","ohne ge-, Endung -t","Wir haben den Balkon fotografiert."],["be-, ver-, er-, ent-, ge-","vorne ohne Betonung","ohne ge-","Ich habe die Rechnung bezahlt."],["be-, ver-, er-, ent-, ge-","vorne ohne Betonung","ohne ge-","Sie hat ihren Schlüssel vergessen."],["an-, auf-, aus-, ein-, mit-, zu-","vorne mit Betonung","ge- nach dem Präfix","Er hat das Formular ausgefüllt."],["an-, auf-, aus-, ein-, mit-, zu-","vorne mit Betonung","ge- nach dem Präfix","Ich habe den Kalender mitgebracht."],["Verb ohne Präfix","nichts vorne","ge- am Anfang","Wir haben einen Kuchen gebacken."]],"highlight_row":-1,"description_de":"Test: Betone das Verb. Ohne Betonung vorne steht kein ge-. Mit Betonung vorne steht ge- in der Mitte.","description_en":"Say the verb out loud and listen to the stress: if the first syllable carries no stress (be-ZAHLT, foto-gra-FIERT), there is no ge- at all. If it does carry the stress (AUS-gefüllt, MIT-gebracht), the prefix is separable and the ge- moves into the middle. Everything else simply keeps ge- at the front."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Stress at the front: ge- in the middle. No stress at the front: no ge- at all.', 'Betonung vorne: ge- in die Mitte. Keine Betonung: kein ge-.', NULL, NULL, 'The same test covers verbs the table does not list: reserviert, funktioniert, bekommen, erklärt (no ge-) against eingekauft, angerufen, aufgeräumt (ge- in the middle).', 'Auch diese Verben haben kein ge-: reserviert, funktioniert, bekommen, erklärt.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1bf98739-369e-53c1-b847-661315030301'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '71823587-c31a-5069-8802-32eadae318a7'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'pattern', 'The Satzklammer in statements and questions', 'Die Satzklammer in Aussagen und Fragen', '{"type":"case_table","headers":["Satztyp","Beispiel","Klammer"],"rows":[["Aussage","Ich habe die Fotos schon gezeigt.","habe … gezeigt"],["Zeit zuerst","Am Montag hat er die Küche geputzt.","hat … geputzt"],["Ja/Nein-Frage","Habt ihr das Zimmer schon aufgeräumt?","Habt … aufgeräumt"],["W-Frage","Wann hast du deine Chefin angerufen?","hast … angerufen"],["Negation","Wir haben den Film nicht verstanden.","haben … verstanden"],["Frage an Sie","Haben Sie gut gefrühstückt?","Haben … gefrühstückt"]],"highlight_row":-1,"description_de":"Am Ende steht immer das Partizip. Nur haben wechselt seinen Platz.","description_en":"The participle never moves: it always closes the sentence. Only haben changes position - second in a statement, first in a yes/no question, second after a question word. Time, object and nicht all sit between the two brackets."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'haben opens the bracket, the participle closes it. Nothing follows the participle.', 'haben öffnet die Klammer, das Partizip schließt sie.', NULL, NULL, 'In a yes/no question haben stands in position 1. With a time phrase first it stays in position 2.', 'In der Ja/Nein-Frage steht haben ganz vorne. Sonst steht es auf Position 2.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '71823587-c31a-5069-8802-32eadae318a7'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1fd9c617-ad8a-5277-a85e-468174507ece'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'common_mistakes', 'Mistakes in the Perfekt with haben', 'Fehler im Perfekt mit haben', '{"intro_de":"Fünf Fehler hört man besonders oft. Prüf sie nach jedem Satz.","intro_en":"Five slips account for most Perfekt errors at A2. Run through them after every sentence you write.","mistakes":[{"wrong":"Er hat das Auto gerepariert.","correct":"Er hat das Auto repariert.","explanation_de":"Bei -ieren fällt das ge- weg.","explanation_en":"Verbs ending in -ieren never take ge-.","memory_trick_en":"-ieren verbs are long enough already."},{"wrong":"Ich habe den Termin gevergessen.","correct":"Ich habe den Termin vergessen.","explanation_de":"ver- ist ein Präfix ohne Betonung. Da steht kein ge-.","explanation_en":"be-, ver-, er-, ent- and ge- carry no stress and replace the ge-."},{"wrong":"Ich habe meinen Koffer packen.","correct":"Ich habe meinen Koffer gepackt.","explanation_de":"Nach haben steht das Partizip, nicht der Infinitiv.","explanation_en":"The Perfekt needs the participle gepackt, not the infinitive packen."},{"wrong":"Wir haben aufgeräumt die Küche.","correct":"Wir haben die Küche aufgeräumt.","explanation_de":"Das Objekt steht vor dem Partizip.","explanation_en":"The participle closes the bracket, so the object comes before it."},{"wrong":"Meine Gäste haben spät angekommen.","correct":"Meine Gäste sind spät angekommen.","explanation_de":"ankommen zeigt Bewegung und nimmt sein.","explanation_en":"ankommen is a movement verb, so it builds the Perfekt with sein, not haben."}]}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Two questions before you write: haben or sein? And does the participle need ge-?', 'Zwei Fragen vor jedem Satz: haben oder sein? Braucht das Partizip ein ge-?', NULL, NULL, 'Most errors are position errors, not vocabulary errors: the participle must be the last word.', 'Viele Fehler sind Positionsfehler. Am Ende steht das Partizip.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1fd9c617-ad8a-5277-a85e-468174507ece'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0814fd91-d2f1-5c1c-a8a2-8b75995b4ba2'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'explanation_patterns', 'Separable verbs and dative pronouns in the imperative', 'Imperativ: Präfix und Dativpronomen', '{"type":"case_table","headers":["Verb","du","ihr","Sie"],"rows":[["ausfüllen","Füll das Formular aus!","Füllt das Formular aus!","Füllen Sie das Formular aus!"],["einladen","Lad deine Freunde ein!","Ladet eure Freunde ein!","Laden Sie Ihre Freunde ein!"],["einkaufen","Kauf bitte ein!","Kauft bitte ein!","Kaufen Sie bitte ein!"],["mitbringen","Bring dein Wörterbuch mit!","Bringt euer Wörterbuch mit!","Bringen Sie Ihr Wörterbuch mit!"],["zurückkommen","Komm bald zurück!","Kommt bald zurück!","Kommen Sie bald zurück!"],["helfen (Dativ-Verb)","Hilf mir bitte!","Helft mir bitte!","Helfen Sie mir bitte!"]],"highlight_row":-1,"description_de":"Das Präfix steht am Satzende. Ein Dativpronomen wie mir steht früh im Satz. Bei Sie kommt es nach Sie.","description_en":"In the imperative a separable verb splits exactly as it does in a normal sentence: the prefix goes to the very end. A dative pronoun (mir, uns, Ihnen) comes early - directly after the verb with du and ihr, directly after Sie in the polite form."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Verb first, prefix last, everything else in between.', 'Verb zuerst, Präfix zuletzt, alles andere dazwischen.', 'With Sie the pronoun follows Sie: Helfen Sie mir bitte! - never Helfen mir Sie.', 'Bei Sie steht das Pronomen nach Sie: Helfen Sie mir bitte!', 'helfen and geben change e to i in the du-form: Hilf! Gib! The prefix still closes the sentence.', 'helfen und geben wechseln e zu i: Hilf! Gib!'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0814fd91-d2f1-5c1c-a8a2-8b75995b4ba2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9f0be5c9-50fc-5fa3-ac22-48ff809721fa'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'tip', 'bitte, mal and doch: sounding friendly', 'bitte, mal und doch: freundlich klingen', '{"type":"case_table","headers":["Wort","Wirkung","Beispiel"],"rows":[["bitte","höflich, immer möglich","Schreib mir bitte eine E-Mail!"],["mal","kurz und locker unter Freunden","Zeig mal dein Foto!"],["doch","macht daraus einen Vorschlag","Geh doch zu Fuß!"],["doch mal","sehr freundlich im Gespräch","Frag doch mal deinen Chef!"],["ohne Wort","kurz, klingt oft hart","Räum dein Zimmer auf!"]],"highlight_row":-1,"description_de":"Ein Imperativ ohne bitte klingt schnell hart. Mit bitte, mal oder doch klingst du freundlich.","description_en":"A bare imperative sounds harsh in German. bitte makes it polite, mal makes it casual, doch turns an order into a suggestion. bitte can stand after the verb or at the end of the sentence."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'bitte = polite, mal = casual, doch = a suggestion rather than an order.', 'bitte = höflich, mal = locker, doch = ein Vorschlag.', 'At an office, a shop or a doctor''s practice always use the Sie-form plus bitte.', 'Im Amt und im Geschäft immer die Sie-Form mit bitte.', 'In the Goethe A2 exam, Sprechen Teil 3 asks two candidates to plan something together. Requests and suggestions - Komm doch um sechs! Helfen Sie mir bitte! - are exactly what that task needs.', 'In der Prüfung Sprechen Teil 3 planst du etwas zusammen. Dort brauchst du Bitten und Vorschläge.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9f0be5c9-50fc-5fa3-ac22-48ff809721fa'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd3b4c8ba-43eb-53f0-96e0-0ecfbd1ddc15'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'common_mistakes', 'Mistakes in the imperative', 'Fehler im Imperativ', '{"intro_de":"Diese fünf Fehler hört man im Unterricht fast täglich.","intro_en":"These five slips come up in almost every class. Check your imperative against them.","mistakes":[{"wrong":"Du warte bitte hier!","correct":"Warte bitte hier!","explanation_de":"Im du-Imperativ steht kein du.","explanation_en":"The du-imperative drops the pronoun. Only the Sie-form keeps Sie."},{"wrong":"Gibt mir bitte die Formulare!","correct":"Gebt mir bitte die Formulare!","explanation_de":"Der Wechsel e zu i gilt nur für du, nicht für ihr.","explanation_en":"The e to i change belongs to the du-form only: Gib! but Gebt!"},{"wrong":"Bringen mir Sie bitte die Rechnung!","correct":"Bringen Sie mir bitte die Rechnung!","explanation_de":"Bei Sie steht das Pronomen nach Sie.","explanation_en":"In the Sie-form the pronoun Sie comes first, and mir follows it."},{"wrong":"Bring zurück bitte das Buch!","correct":"Bring bitte das Buch zurück!","explanation_de":"Das Präfix kommt ans Satzende.","explanation_en":"The separable prefix always closes the sentence, after the object."},{"wrong":"Bezahlen bitte an der Kasse!","correct":"Bezahlen Sie bitte an der Kasse!","explanation_de":"In der Sie-Form fehlt hier das Pronomen Sie.","explanation_en":"The Sie-imperative always keeps the pronoun: Bezahlen Sie!"}]}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'e to i stays with du, a to ä disappears everywhere.', 'e zu i bleibt bei du, a zu ä geht weg.', NULL, NULL, 'Three checks before you speak: no du, the right vowel, the prefix at the end.', 'Drei Kontrollen: kein du, der Vokal, das Präfix am Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd3b4c8ba-43eb-53f0-96e0-0ecfbd1ddc15'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5e782c94-9733-5192-b980-b3ba9371ca4b'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'Unsere Nachbarin arbeitet in einer Apotheke.', 'Our neighbour works in a pharmacy.', 'Unsere', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'Nachbarin is feminine nominative, so unser takes -e, exactly like eine.', 'Nachbarin ist feminin und Nominativ: unsere.', '{"Unsere":"our (nom. fem.)","Nachbarin":"neighbour (female)","arbeitet":"works","in":"in","einer":"a (dat. fem.)","Apotheke":"pharmacy"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5e782c94-9733-5192-b980-b3ba9371ca4b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e847be0c-08d5-5667-8d16-71036354c16a'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'Euer Kalender hängt in der Küche.', 'Your calendar is hanging in the kitchen.', 'Euer', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'Masculine nominative takes no ending, so euer keeps its e: euer Kalender.', 'Maskulin Nominativ ohne Endung: euer Kalender.', '{"Euer":"your (pl., nom. masc.)","Kalender":"calendar","hängt":"hangs","in":"in","der":"the (dat. fem.)","Küche":"kitchen"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e847be0c-08d5-5667-8d16-71036354c16a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '52a630f0-411f-5b97-8f12-9d3294df8810'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'Das Zimmer gefällt meinen Eltern.', 'My parents like the room.', 'meinen', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'gefallen is a dative verb, and Eltern is plural, so the ending is -en.', 'gefallen braucht den Dativ. Plural: meinen Eltern.', '{"Das":"the (nom. neut.)","Zimmer":"room","gefällt":"is pleasing to, appeals to","meinen":"my (dat. pl.)","Eltern":"parents"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '52a630f0-411f-5b97-8f12-9d3294df8810'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '985326e0-931d-56d3-8d4a-39cbe757c994'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 'Ihr Zug fährt um neun Uhr, Frau Sommer.', 'Your train leaves at nine, Mrs Sommer.', 'Ihr', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'Zug is masculine nominative, so the polite Ihr takes no ending.', 'Zug ist maskulin und Nominativ: Ihr ohne Endung.', '{"Ihr":"your (formal, nom. masc.)","Zug":"train","fährt":"leaves, goes","um":"at","neun":"nine","Uhr":"o''clock","Frau":"Mrs","Sommer":"Sommer"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '985326e0-931d-56d3-8d4a-39cbe757c994'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a4e1efb8-c69c-5e4e-8f58-b6e587dcade6'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'Meine Oma hat eine Geschichte erzählt.', 'My grandma told a story.', 'erzählt', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'erzählen carries no stress on er-, so the participle has no ge-: erzählt.', 'er- steht ohne Betonung. Das Partizip hat kein ge-.', '{"Meine":"my (nom. fem.)","Oma":"grandma","hat":"has","eine":"a (acc. fem.)","Geschichte":"story","erzählt":"told (participle)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a4e1efb8-c69c-5e4e-8f58-b6e587dcade6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a6c2d969-f794-5af6-b609-513d484db2ad'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'Wir haben am Sonntag lange telefoniert.', 'We were on the phone for a long time on Sunday.', 'telefoniert', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'telefonieren ends in -ieren, so the participle is telefoniert, with no ge-.', 'telefonieren endet auf -ieren: kein ge-.', '{"Wir":"we","haben":"have","am":"on","Sonntag":"Sunday","lange":"for a long time","telefoniert":"phoned (participle)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a6c2d969-f794-5af6-b609-513d484db2ad'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '87a7fba8-4cf2-506e-92b0-3ea64e07d07c'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'Habt ihr die Rechnung schon bekommen?', 'Have you received the bill yet?', 'bekommen', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'In a yes/no question habt comes first; bekommen keeps its prefix and takes no ge-.', 'In der Ja/Nein-Frage steht habt vorne. bekommen hat kein ge-.', '{"Habt":"have","ihr":"you (pl.)","die":"the (acc. fem.)","Rechnung":"bill","schon":"already, yet","bekommen":"received (participle)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '87a7fba8-4cf2-506e-92b0-3ea64e07d07c'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '28b51a51-a579-5632-8b0c-e2ba61b0bb8f'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 'Am Freitag hat der Lehrer die Regel erklärt.', 'On Friday the teacher explained the rule.', 'erklärt', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'The time phrase takes position 1, so hat stays in position 2 and erklärt closes the sentence.', 'Die Zeit steht vorne, hat bleibt auf Position 2.', '{"Am":"on","Freitag":"Friday","hat":"has","der":"the (nom. masc.)","Lehrer":"teacher","die":"the (acc. fem.)","Regel":"rule","erklärt":"explained (participle)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '28b51a51-a579-5632-8b0c-e2ba61b0bb8f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '38086c90-949b-5a5c-8393-6199b8cb490f'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'Machen Sie bitte das Licht an!', 'Please switch the light on.', 'Machen Sie', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sie-form: infinitive + Sie, and the separable prefix an closes the sentence.', 'Sie-Form: Infinitiv plus Sie. Das Präfix an steht am Ende.', '{"Machen":"make, do (Sie-imperative)","Sie":"you (formal)","bitte":"please","das":"the (acc. neut.)","Licht":"light","an":"on (separable prefix)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '38086c90-949b-5a5c-8393-6199b8cb490f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6079ce98-c1a6-5690-bc4d-681f2977c67a'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'Kommt doch am Sonntag zu uns!', 'Why don''t you come to our place on Sunday?', 'Kommt', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ihr-imperative equals the normal ihr-form, and doch turns the order into a suggestion.', 'ihr-Imperativ wie die ihr-Form. doch macht daraus einen Vorschlag.', '{"Kommt":"come (ihr-imperative)","doch":"(friendly suggestion)","am":"on","Sonntag":"Sunday","zu":"to","uns":"us (dative)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6079ce98-c1a6-5690-bc4d-681f2977c67a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '9bed4240-076a-5315-b931-893e4d410656'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'Hol bitte die Kinder ab!', 'Please pick the children up.', 'Hol', NULL, 11, '2026-09-05T12:00:00+00:00'::timestamptz, 'abholen is separable: the stem Hol opens the sentence, the prefix ab closes it.', 'abholen ist trennbar: Hol vorne, ab am Ende.', '{"Hol":"fetch, pick up (du-imperative)","bitte":"please","die":"the (acc. pl.)","Kinder":"children","ab":"(separable prefix of abholen)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '9bed4240-076a-5315-b931-893e4d410656'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'cc88493f-c3c9-5b62-a2fb-ad85f8c0f5aa'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 'Zeigen Sie mir bitte Ihren Ausweis!', 'Please show me your ID.', 'Zeigen Sie', NULL, 12, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Sie-form the pronoun Sie comes first and the dative pronoun mir follows it.', 'Bei der Sie-Form steht Sie vorne, dann kommt mir.', '{"Zeigen":"show (Sie-imperative)","Sie":"you (formal)","mir":"me (dative)","bitte":"please","Ihren":"your (acc. masc., formal)","Ausweis":"ID card"}'::jsonb, 3, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'cc88493f-c3c9-5b62-a2fb-ad85f8c0f5aa'::uuid);

-- Exercises
INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '71b24aca-40f0-5d8a-86ef-b5eef1c51d9d'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 4, 'fill_blank', 'Der Koffer gehört ___ Onkel. (mein Onkel)', 'The suitcase belongs to my uncle. Type the possessive: gehören takes the dative, masculine ''mein''.', NULL, 'meinem', '["meinem"]'::jsonb, 'gehören always takes a dative object, and in the masculine dative mein becomes meinem.', 'gehören hat immer ein Dativobjekt. Maskulin: mein → meinem.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem gehört der Koffer? Meinem Onkel. Masculine dative: mein → meinem.', 'Wem gehört der Koffer? Meinem Onkel. Maskulin Dativ: mein → meinem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '71b24aca-40f0-5d8a-86ef-b5eef1c51d9d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5bc350a8-c0cd-54ae-9bd8-9ba07e5df06d'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 4, 'fill_blank', 'Der Kuchen schmeckt ___ Schwester. (meine Schwester)', 'The cake tastes good to my sister. Type the possessive: schmecken takes the dative, feminine ''meine''.', NULL, 'meiner', '["meiner"]'::jsonb, 'schmecken takes a dative object, and in the feminine dative meine becomes meiner.', 'schmecken hat ein Dativobjekt. Feminin: meine → meiner.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem schmeckt der Kuchen? Meiner Schwester. Feminine dative: meine → meiner.', 'Wem schmeckt der Kuchen? Meiner Schwester. Feminin Dativ: meine → meiner.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5bc350a8-c0cd-54ae-9bd8-9ba07e5df06d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b01e7262-8232-5ba4-b809-31da34c013b6'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 4, 'fill_blank', 'Ich kaufe ___ Kind ein Eis. (ein Kind)', 'I am buying a child an ice cream. Type the indefinite article: neuter dative for the person who gets it.', NULL, 'einem', '["einem"]'::jsonb, 'Kind is the person who receives, so it stands in the dative: ein becomes einem.', 'Kind ist hier das Dativobjekt. Neutrum: ein → einem.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem kaufe ich ein Eis? Einem Kind. Neuter dative: ein → einem.', 'Wem kaufe ich ein Eis? Einem Kind. Neutrum Dativ: ein → einem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b01e7262-8232-5ba4-b809-31da34c013b6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4bc59e34-e17d-5b5e-b6e3-0c6f8b3eedf1'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 4, 'fill_blank', 'Die Wohnung gefällt ___ sehr gut. (wir)', 'We like the flat a lot. Type the dative pronoun for ''wir''.', NULL, 'uns', '["uns"]'::jsonb, 'gefallen takes a dative object, so wir becomes the dative pronoun uns.', 'gefallen hat ein Dativobjekt. wir wird im Dativ zu uns.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem gefällt die Wohnung? Uns. The dative form of wir is uns.', 'Wem gefällt die Wohnung? Uns. Die Dativform von wir ist uns.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4bc59e34-e17d-5b5e-b6e3-0c6f8b3eedf1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '86fb31bd-0920-53da-b4e3-c074bc3a94b8'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / helfen / unsere Nachbarin]', 'Write the sentence: We help our neighbour (female). Verb helfen, subject wir; the object goes into the dative.', NULL, 'Wir helfen unserer Nachbarin.', '["Wir helfen unserer Nachbarin.","Wir helfen unserer Nachbarin"]'::jsonb, 'helfen never takes an accusative object; its object is always dative.', 'helfen hat nie ein Akkusativobjekt. Das Objekt steht immer im Dativ.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem helfen wir? Unserer Nachbarin. Feminine dative: unsere → unserer.', 'Wem helfen wir? Unserer Nachbarin. Feminin Dativ: unsere → unserer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '86fb31bd-0920-53da-b4e3-c074bc3a94b8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f12d3239-4b64-5b68-93ac-20d45c459deb'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Mantel / gehören / die Lehrerin]', 'Write the sentence: The coat belongs to the teacher (female). Start with ''Der Mantel''; gehören takes the dative.', NULL, 'Der Mantel gehört der Lehrerin.', '["Der Mantel gehört der Lehrerin.","Der Mantel gehört der Lehrerin"]'::jsonb, 'The subject der Mantel stays nominative; die Lehrerin becomes der Lehrerin in the dative.', 'Das Subjekt der Mantel bleibt Nominativ. die Lehrerin wird zu der Lehrerin.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem gehört der Mantel? Der Lehrerin. Feminine dative: die → der.', 'Wem gehört der Mantel? Der Lehrerin. Feminin Dativ: die → der.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f12d3239-4b64-5b68-93ac-20d45c459deb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a5dc5302-6bcc-5458-a267-4554c79561a3'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / schenken / unsere Eltern / eine Reise]', 'Write the sentence: We give our parents a trip as a present. Start with ''Wir''; dative object before accusative object.', NULL, 'Wir schenken unseren Eltern eine Reise.', '["Wir schenken unseren Eltern eine Reise.","Wir schenken unseren Eltern eine Reise"]'::jsonb, 'The person who receives is dative and comes first; the thing given is accusative.', 'Die Person im Dativ kommt zuerst, die Sache im Akkusativ danach.', 'Wem? zuerst, was? danach.', 22, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The possessive shows the dative plural here: unsere → unseren, and dative comes before accusative.', 'Im Dativ Plural: unsere → unseren. Dativ steht vor Akkusativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a5dc5302-6bcc-5458-a267-4554c79561a3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e8a171ce-d5d1-548d-bb9a-4b9928ff86ff'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / zeigen / mein Freund / die Fotos]', 'Write the sentence: I show my friend the photos. Start with ''Ich''; dative person first, accusative thing second.', NULL, 'Ich zeige meinem Freund die Fotos.', '["Ich zeige meinem Freund die Fotos.","Ich zeige meinem Freund die Fotos"]'::jsonb, 'mein Freund is the person who receives (dative); die Fotos is the direct object (accusative).', 'mein Freund ist das Dativobjekt. die Fotos ist das Akkusativobjekt.', 'Wem? → meinem Freund.', 23, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem zeige ich? Meinem Freund. Was zeige ich? Die Fotos. Plural die stays die.', 'Wem zeige ich? Meinem Freund. Was zeige ich? Die Fotos. Plural die bleibt die.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e8a171ce-d5d1-548d-bb9a-4b9928ff86ff'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1305ca9a-0fe1-5bff-a283-5f6e4f6c879c'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Die Jacke passt mich nicht.“', 'Correct the sentence: passen takes a dative pronoun, not an accusative one. Write the whole sentence.', NULL, 'Die Jacke passt mir nicht.', '["Die Jacke passt mir nicht.","Die Jacke passt mir nicht"]'::jsonb, 'mich is accusative; passen needs the dative pronoun mir.', 'mich ist Akkusativ. passen braucht das Dativpronomen mir.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem passt die Jacke nicht? Mir. The dative of ich is mir.', 'Wem passt die Jacke nicht? Mir. Der Dativ von ich ist mir.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1305ca9a-0fe1-5bff-a283-5f6e4f6c879c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef8ff1ca-eab3-5207-a617-b60d087d4d80'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Ich schreibe meine Schwester eine E-Mail.“', 'Correct the sentence: the person who receives the e-mail must be dative. Write the whole sentence.', NULL, 'Ich schreibe meiner Schwester eine E-Mail.', '["Ich schreibe meiner Schwester eine E-Mail.","Ich schreibe meiner Schwester eine E-Mail"]'::jsonb, 'meine Schwester is the person who receives, so it takes the dative: meiner Schwester.', 'meine Schwester bekommt die E-Mail. Das ist der Dativ: meiner Schwester.', NULL, 25, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem schreibe ich? Meiner Schwester. Was schreibe ich? Eine E-Mail.', 'Wem schreibe ich? Meiner Schwester. Was schreibe ich? Eine E-Mail.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef8ff1ca-eab3-5207-a617-b60d087d4d80'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '671e18d4-4c76-5c50-8bed-9e190233e076'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Wir helfen die Kinder.“', 'Correct the sentence: helfen takes the dative, and the dative plural also needs an -n on the noun. Write the whole sentence.', NULL, 'Wir helfen den Kindern.', '["Wir helfen den Kindern.","Wir helfen den Kindern"]'::jsonb, 'In the dative plural the article becomes den and the noun itself adds -n.', 'Im Dativ Plural wird der Artikel zu den. Das Nomen bekommt auch ein -n.', 'Der Dativ Plural endet auf -n.', 26, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem helfen wir? Den Kindern. Dative plural: die Kinder → den Kindern.', 'Wem helfen wir? Den Kindern. Dativ Plural: die Kinder → den Kindern.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '671e18d4-4c76-5c50-8bed-9e190233e076'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd081c664-4c23-56ba-bfc3-3d6fce6ef9b2'::uuid, '998ad04c-e261-43b7-8a58-e596053f64ba'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Der Kellner bringt die Frau die Rechnung.“', 'Correct the sentence: the person who receives must be dative. Write the whole sentence.', NULL, 'Der Kellner bringt der Frau die Rechnung.', '["Der Kellner bringt der Frau die Rechnung.","Der Kellner bringt der Frau die Rechnung","Der Kellner bringt die Rechnung der Frau.","Der Kellner bringt die Rechnung der Frau"]'::jsonb, 'die Frau receives the bill, so it takes the dative: der Frau. die Rechnung stays accusative.', 'die Frau bekommt die Rechnung. Sie steht im Dativ: der Frau.', NULL, 27, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wem bringt der Kellner? Der Frau. Was? Die Rechnung. Dative comes first.', 'Wem bringt der Kellner? Der Frau. Was? Die Rechnung. Der Dativ kommt zuerst.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd081c664-4c23-56ba-bfc3-3d6fce6ef9b2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b018bf6a-afb1-55f1-a20c-394ab0c611df'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 4, 'fill_blank', 'Ich spreche oft mit ___ Nachbarin. (die Nachbarin)', 'I often talk to the neighbour (female). Type the article: mit always takes the dative, feminine.', NULL, 'der', '["der"]'::jsonb, 'mit is a dative preposition, so die Nachbarin becomes der Nachbarin.', 'mit ist eine Dativpräposition. Feminin: die → der.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit + Dativ: die Nachbarin → der Nachbarin.', 'mit + Dativ: die Nachbarin → der Nachbarin.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b018bf6a-afb1-55f1-a20c-394ab0c611df'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1b5011bb-9456-5b11-a63b-8f2f83283886'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 4, 'fill_blank', 'Nach ___ Arbeit gehe ich einkaufen. (die Arbeit)', 'After work I go shopping. Type the article: here nach is a time preposition and takes the dative.', NULL, 'der', '["der"]'::jsonb, 'nach is a dative preposition, so die Arbeit becomes der Arbeit.', 'nach ist eine Dativpräposition. die Arbeit wird zu der Arbeit.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'nach + Dativ: die Arbeit → der Arbeit. The verb stays in position two.', 'nach + Dativ: die Arbeit → der Arbeit. Das Verb bleibt auf Position zwei.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1b5011bb-9456-5b11-a63b-8f2f83283886'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3e1a59c2-f1c6-553a-a562-881aa7362f78'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 4, 'fill_blank', 'Wir wohnen seit ___ Monat in Berlin. (ein Monat)', 'We have been living in Berlin for a month. Type the article: seit takes the dative, masculine.', NULL, 'einem', '["einem"]'::jsonb, 'seit is a dative preposition, so ein Monat becomes einem Monat.', 'seit ist eine Dativpräposition. Maskulin: ein → einem.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'seit + Dativ: ein Monat → einem Monat, and German uses the present tense here.', 'seit + Dativ: ein Monat → einem Monat. Deutsch benutzt hier das Präsens.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3e1a59c2-f1c6-553a-a562-881aa7362f78'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b259d659-8991-574e-8cce-b13590951321'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 4, 'fill_blank', 'Am Samstag fahre ich ___ Flughafen. (zu + dem)', 'On Saturday I drive to the airport. Type the short form of zu + dem (the long form counts too).', NULL, 'zum', '["zum","zu dem"]'::jsonb, 'zu takes the dative, and out of zu + dem you normally make zum.', 'zu steht mit Dativ. Aus zu + dem macht man normalerweise zum.', NULL, 19, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'zu dem Flughafen → zum Flughafen. The short form is the everyday one.', 'zu dem Flughafen → zum Flughafen. Die Kurzform ist die Alltagsform.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b259d659-8991-574e-8cce-b13590951321'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd9fd88e4-eb02-58f2-88ce-c9ff80231051'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / fahren / mit / mein Fahrrad / zu / die Arbeit]', 'Write the sentence: I ride my bike to work. Both prepositions take the dative; either word order counts.', NULL, 'Ich fahre mit meinem Fahrrad zur Arbeit.', '["Ich fahre mit meinem Fahrrad zur Arbeit.","Ich fahre mit meinem Fahrrad zur Arbeit","Mit meinem Fahrrad fahre ich zur Arbeit.","Mit meinem Fahrrad fahre ich zur Arbeit"]'::jsonb, 'mit + Dativ gives meinem Fahrrad; zu + der Arbeit becomes zur Arbeit.', 'mit + Dativ: meinem Fahrrad. zu + der Arbeit wird zur Arbeit.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mein → meinem after mit; zu der Arbeit → zur Arbeit.', 'mein → meinem nach mit. zu der Arbeit → zur Arbeit.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd9fd88e4-eb02-58f2-88ce-c9ff80231051'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '945f4a8c-441c-508b-9d55-ea205a2a4d0e'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / arbeiten / seit / drei Monate / in Hamburg]', 'Write the sentence: I have been working in Hamburg for three months. Start with ''Ich''; seit takes the dative plural.', NULL, 'Ich arbeite seit drei Monaten in Hamburg.', '["Ich arbeite seit drei Monaten in Hamburg.","Ich arbeite seit drei Monaten in Hamburg"]'::jsonb, 'seit takes the dative, and the dative plural adds -n: drei Monate → drei Monaten.', 'seit steht mit Dativ. Der Dativ Plural bekommt -n: drei Monate → drei Monaten.', 'Der Dativ Plural endet auf -n.', 21, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'German uses the present tense with seit, and the dative plural ends in -n.', 'Deutsch benutzt mit seit das Präsens. Der Dativ Plural endet auf -n.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '945f4a8c-441c-508b-9d55-ea205a2a4d0e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3a1c5946-5900-5b6b-8745-d197cdf37557'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'sentence_building', 'Schreib den Satz: [nach / das Abendessen / ich / anrufen / meine Freundin]', 'Write the sentence: After dinner I call my friend (female). Start with ''Nach''; anrufen is separable.', NULL, 'Nach dem Abendessen rufe ich meine Freundin an.', '["Nach dem Abendessen rufe ich meine Freundin an.","Nach dem Abendessen rufe ich meine Freundin an"]'::jsonb, 'nach + dem Abendessen fills position one, so the verb comes second and ich follows it.', 'nach + dem Abendessen steht auf Position eins. Das Verb kommt auf Position zwei.', 'Das Verb steht auf Position zwei.', 22, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time phrase first means inversion: rufe ich; the prefix an goes to the end.', 'Zeitangabe zuerst bedeutet Inversion: rufe ich. Das Präfix an steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3a1c5946-5900-5b6b-8745-d197cdf37557'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c18e0311-43e1-5874-8423-da9f919b1340'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / fahren / heute / zu / der Arzt]', 'Write the sentence: I drive to the doctor today. Start with ''Ich''; the short form is the everyday one.', NULL, 'Ich fahre heute zum Arzt.', '["Ich fahre heute zum Arzt.","Ich fahre heute zum Arzt","Ich fahre heute zu dem Arzt.","Ich fahre heute zu dem Arzt"]'::jsonb, 'zu takes the dative: der Arzt → dem Arzt, normally shortened to zum Arzt.', 'zu steht mit Dativ: der Arzt → dem Arzt. Meistens sagt man zum Arzt.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both zum Arzt and zu dem Arzt are correct; zum is the everyday form.', 'zum Arzt und zu dem Arzt sind beide richtig. zum ist die Alltagsform.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c18e0311-43e1-5874-8423-da9f919b1340'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0d5d1352-3e65-5609-bc41-99dd327f4eb1'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Heute Abend gehe ich bei meinen Freunden.“', 'Correct the sentence: bei says where you are, but this sentence says where you are going. Write the whole sentence.', NULL, 'Heute Abend gehe ich zu meinen Freunden.', '["Heute Abend gehe ich zu meinen Freunden.","Heute Abend gehe ich zu meinen Freunden"]'::jsonb, 'bei answers wo? (Ich bin bei Freunden); for the direction you need zu + Dativ.', 'bei antwortet auf wo?: Ich bin bei Freunden. Für die Richtung braucht man zu.', 'Wohin? → zu.', 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'gehen shows a direction, so zu meinen Freunden is right; both keep the dative.', 'gehen zeigt eine Richtung, deshalb passt zu meinen Freunden. Beide stehen mit Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0d5d1352-3e65-5609-bc41-99dd327f4eb1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8d3eea6e-d446-52ef-a805-a0a64ef83874'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Ich arbeite bei eine Firma.“', 'Correct the sentence: bei takes the dative. Write the whole sentence.', NULL, 'Ich arbeite bei einer Firma.', '["Ich arbeite bei einer Firma.","Ich arbeite bei einer Firma"]'::jsonb, 'bei is a dative preposition, so eine Firma becomes einer Firma.', 'bei ist eine Dativpräposition. Feminin: eine → einer.', NULL, 25, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'bei + Dativ: eine Firma → einer Firma.', 'bei + Dativ: eine Firma → einer Firma.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8d3eea6e-d446-52ef-a805-a0a64ef83874'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c295fc4f-21b1-5f85-bc04-d15eb5bce594'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Seit einem Monat habe ich jeden Tag Gitarre gespielt.“', 'Correct the sentence: the activity is still going on every day, and with seit German then uses the present tense. Start with ''Seit einem Monat''.', NULL, 'Seit einem Monat spiele ich jeden Tag Gitarre.', '["Seit einem Monat spiele ich jeden Tag Gitarre.","Seit einem Monat spiele ich jeden Tag Gitarre"]'::jsonb, 'seit plus something that still happens every day needs the present tense, not the Perfekt.', 'seit und etwas, das jeden Tag weiterläuft: Da steht das Präsens, nicht das Perfekt.', 'seit + Präsens.', 26, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Seit einem Monat spiele ich jeden Tag: it still goes on today, so present tense.', 'Seit einem Monat spiele ich jeden Tag: Es läuft noch heute, also Präsens.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c295fc4f-21b1-5f85-bc04-d15eb5bce594'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bb24191a-f862-504e-8b91-0a6d6d5fbc61'::uuid, 'bbcc1858-0fb2-4185-8b85-9b83c457bf81'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Die Apotheke ist gegenüber der Supermarkt.“', 'Correct the sentence: gegenüber takes the dative, masculine. Write the whole sentence (gegenüber may also stand after the noun).', NULL, 'Die Apotheke ist gegenüber dem Supermarkt.', '["Die Apotheke ist gegenüber dem Supermarkt.","Die Apotheke ist gegenüber dem Supermarkt","Die Apotheke ist dem Supermarkt gegenüber.","Die Apotheke ist dem Supermarkt gegenüber"]'::jsonb, 'gegenüber is a dative preposition, so der Supermarkt becomes dem Supermarkt.', 'gegenüber ist eine Dativpräposition. der Supermarkt wird zu dem Supermarkt.', NULL, 27, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'gegenüber + Dativ: der → dem. gegenüber may stand before or after the noun.', 'gegenüber + Dativ: der → dem. gegenüber kann vor oder nach dem Nomen stehen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bb24191a-f862-504e-8b91-0a6d6d5fbc61'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '50febe97-44e2-5ab9-923c-226a129c3001'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 4, 'fill_blank', 'Die Kinder spielen ___ Garten. (in + dem, wo?)', 'The children are playing in the garden. Type the short form of in + dem (the long form counts too).', NULL, 'im', '["im","in dem"]'::jsonb, 'The question is wo?, so in takes the dative, and in + dem gives im.', 'Die Frage ist wo?, deshalb steht in mit Dativ. in + dem wird im.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo spielen die Kinder? Im Garten. Location means dative.', 'Wo spielen die Kinder? Im Garten. Position bedeutet Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '50febe97-44e2-5ab9-923c-226a129c3001'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '391c40a6-d205-5c00-801a-b7d66be585b5'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 4, 'fill_blank', 'Stell die Flasche bitte auf ___ Tisch. (wohin? der Tisch)', 'Please put the bottle on the table. Type the article: stellen answers wohin?, so accusative, masculine.', NULL, 'den', '["den"]'::jsonb, 'stellen describes movement to a place, so auf takes the accusative.', 'stellen beschreibt eine Bewegung zu einem Ort, deshalb steht auf mit Akkusativ.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohin stelle ich die Flasche? Auf den Tisch. Movement means accusative.', 'Wohin stelle ich die Flasche? Auf den Tisch. Bewegung bedeutet Akkusativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '391c40a6-d205-5c00-801a-b7d66be585b5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0b62bf2c-7209-55be-b7a9-6375c01cf943'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 4, 'fill_blank', 'Das Auto steht vor ___ Haus. (wo? das Haus)', 'The car is parked in front of the house. Type the article: stehen answers wo?, so dative, neuter.', NULL, 'dem', '["dem"]'::jsonb, 'stehen describes a position, so vor takes the dative.', 'stehen beschreibt eine Position, deshalb steht vor mit Dativ.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo steht das Auto? Vor dem Haus. Neuter dative: das → dem.', 'Wo steht das Auto? Vor dem Haus. Neutrum Dativ: das → dem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0b62bf2c-7209-55be-b7a9-6375c01cf943'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1b45f97a-9c76-5afd-9290-a07660c3b2a0'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 4, 'fill_blank', 'Wir warten ___ Bahnhof. (an + dem, wo?)', 'We are waiting at the station. Type the short form of an + dem (the long form counts too).', NULL, 'am', '["am","an dem"]'::jsonb, 'warten describes a position, so an takes the dative, and an + dem gives am.', 'warten beschreibt eine Position, deshalb steht an mit Dativ. an + dem wird am.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo warten wir? Am Bahnhof. Location means dative, not accusative.', 'Wo warten wir? Am Bahnhof. Position bedeutet Dativ, nicht Akkusativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1b45f97a-9c76-5afd-9290-a07660c3b2a0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '76a40f0e-0da9-5c71-a392-6aa3fdb3cccd'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / stellen / die Lampe / neben / das Sofa]', 'Write the sentence: I put the lamp next to the sofa. Start with ''Ich''; stellen answers wohin?.', NULL, 'Ich stelle die Lampe neben das Sofa.', '["Ich stelle die Lampe neben das Sofa.","Ich stelle die Lampe neben das Sofa"]'::jsonb, 'stellen means movement to a place, so neben takes the accusative.', 'stellen bedeutet Bewegung zu einem Ort, deshalb steht neben mit Akkusativ.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohin stelle ich die Lampe? Neben das Sofa. Neuter das stays das in the accusative.', 'Wohin stelle ich die Lampe? Neben das Sofa. Neutrum: das bleibt im Akkusativ das.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '76a40f0e-0da9-5c71-a392-6aa3fdb3cccd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'eaae92fe-c2c5-59ea-994f-6eca1bbfd3d9'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'sentence_building', 'Schreib den Satz: [die Schuhe / stehen / hinter / die Tür]', 'Write the sentence: The shoes are behind the door. Start with ''Die Schuhe''; stehen answers wo?.', NULL, 'Die Schuhe stehen hinter der Tür.', '["Die Schuhe stehen hinter der Tür.","Die Schuhe stehen hinter der Tür"]'::jsonb, 'stehen describes a position, so hinter takes the dative: die Tür → der Tür.', 'stehen beschreibt eine Position, deshalb steht hinter mit Dativ: die Tür → der Tür.', NULL, 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo stehen die Schuhe? Hinter der Tür. Position verb, so dative.', 'Wo stehen die Schuhe? Hinter der Tür. Positionsverb, also Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'eaae92fe-c2c5-59ea-994f-6eca1bbfd3d9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8753f741-1e98-5bf5-867b-1db7d71a655f'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / fahren / am Sonntag / an / das Meer]', 'Write the sentence: On Sunday we drive to the sea. Start with ''Wir''; fahren answers wohin?.', NULL, 'Wir fahren am Sonntag ans Meer.', '["Wir fahren am Sonntag ans Meer.","Wir fahren am Sonntag ans Meer","Wir fahren am Sonntag an das Meer.","Wir fahren am Sonntag an das Meer"]'::jsonb, 'fahren means movement, so an takes the accusative, and an + das gives ans.', 'fahren bedeutet Bewegung, deshalb steht an mit Akkusativ. an + das wird ans.', NULL, 22, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohin fahren wir? Ans Meer. Both ans and an das are correct.', 'Wohin fahren wir? Ans Meer. ans und an das sind beide richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8753f741-1e98-5bf5-867b-1db7d71a655f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '98c23539-f978-5020-9b51-d7a6b4819a92'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Schlüssel / liegen / zwischen / die Bücher]', 'Write the sentence: The key is lying between the books. Start with ''Der Schlüssel''; liegen answers wo?.', NULL, 'Der Schlüssel liegt zwischen den Büchern.', '["Der Schlüssel liegt zwischen den Büchern.","Der Schlüssel liegt zwischen den Büchern"]'::jsonb, 'liegen describes a position, so zwischen takes the dative; the dative plural adds -n.', 'liegen beschreibt eine Position, deshalb steht zwischen mit Dativ. Der Dativ Plural bekommt -n.', 'Der Dativ Plural endet auf -n.', 23, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo liegt der Schlüssel? Zwischen den Büchern. Dative plural: die Bücher → den Büchern.', 'Wo liegt der Schlüssel? Zwischen den Büchern. Dativ Plural: die Bücher → den Büchern.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '98c23539-f978-5020-9b51-d7a6b4819a92'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '11200c3e-f264-5100-88dd-6cd32c2265b7'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Leg den Brief bitte in dem Briefkasten.“', 'Correct the sentence: legen answers wohin?, so the case after in is wrong. Write the whole sentence.', NULL, 'Leg den Brief bitte in den Briefkasten.', '["Leg den Brief bitte in den Briefkasten.","Leg den Brief bitte in den Briefkasten!","Leg den Brief bitte in den Briefkasten","Lege den Brief bitte in den Briefkasten.","Lege den Brief bitte in den Briefkasten!","Lege den Brief bitte in den Briefkasten","Bitte leg den Brief in den Briefkasten.","Bitte leg den Brief in den Briefkasten!","Bitte leg den Brief in den Briefkasten","Bitte lege den Brief in den Briefkasten.","Bitte lege den Brief in den Briefkasten!","Bitte lege den Brief in den Briefkasten"]'::jsonb, 'legen is a movement verb, so in needs the accusative den Briefkasten.', 'legen ist ein Bewegungsverb, deshalb braucht in den Akkusativ den Briefkasten.', NULL, 24, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohin lege ich den Brief? In den Briefkasten. legen → Akkusativ, liegen → Dativ.', 'Wohin lege ich den Brief? In den Briefkasten. legen → Akkusativ, liegen → Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '11200c3e-f264-5100-88dd-6cd32c2265b7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9ff35f37-1f00-58db-b107-a7d2a7fed159'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Das Kind sitzt auf den Stuhl.“', 'Correct the sentence: sitzen answers wo?, so the case after auf is wrong. Write the whole sentence.', NULL, 'Das Kind sitzt auf dem Stuhl.', '["Das Kind sitzt auf dem Stuhl.","Das Kind sitzt auf dem Stuhl"]'::jsonb, 'sitzen describes a position, so auf needs the dative dem Stuhl.', 'sitzen beschreibt eine Position, deshalb braucht auf den Dativ dem Stuhl.', NULL, 25, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo sitzt das Kind? Auf dem Stuhl. sitzen → Dativ, setzen → Akkusativ.', 'Wo sitzt das Kind? Auf dem Stuhl. sitzen → Dativ, setzen → Akkusativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9ff35f37-1f00-58db-b107-a7d2a7fed159'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '023880fc-3508-513e-bddd-e2187b4b7acc'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Hängen Sie das Bild bitte über dem Sofa.“', 'Correct the sentence: here hängen means putting the picture up, so it answers wohin?. Write the whole sentence.', NULL, 'Hängen Sie das Bild bitte über das Sofa.', '["Hängen Sie das Bild bitte über das Sofa.","Hängen Sie das Bild bitte über das Sofa!","Hängen Sie das Bild bitte über das Sofa","Hängen Sie bitte das Bild über das Sofa.","Hängen Sie bitte das Bild über das Sofa!","Hängen Sie bitte das Bild über das Sofa"]'::jsonb, 'With a direct object, hängen describes movement, so über takes the accusative.', 'Mit einem Akkusativobjekt beschreibt hängen eine Bewegung. über steht mit Akkusativ.', 'Es gibt hier ein Akkusativobjekt: das Bild.', 26, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohin hängen Sie das Bild? Über das Sofa. The picture moves to a new place.', 'Wohin hängen Sie das Bild? Über das Sofa. Es gibt hier eine Bewegung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '023880fc-3508-513e-bddd-e2187b4b7acc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3f14036c-fa3a-59c4-a13b-d356f917808b'::uuid, 'c3212e59-f9a3-4075-926e-4cf51af2a287'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Ich warte vor die Schule.“', 'Correct the sentence: warten answers wo?, so the case after vor is wrong. Write the whole sentence.', NULL, 'Ich warte vor der Schule.', '["Ich warte vor der Schule.","Ich warte vor der Schule"]'::jsonb, 'warten describes a position, so vor needs the dative der Schule.', 'warten beschreibt eine Position, deshalb braucht vor den Dativ der Schule.', NULL, 27, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wo warte ich? Vor der Schule. No movement, so dative.', 'Wo warte ich? Vor der Schule. Keine Bewegung, also Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3f14036c-fa3a-59c4-a13b-d356f917808b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6e623ea2-493e-53f9-9bbd-39d9e39f6ca3'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 4, 'fill_blank', '___ Chefin kommt aus Wien. (ihr)', 'Her boss comes from Vienna. Feminine noun, nominative, first word of the sentence. Base form: ihr.', NULL, 'Ihre', '["Ihre","ihre"]'::jsonb, 'Chefin is feminine nominative, so ihr takes -e, exactly like eine.', 'Chefin ist feminin und Nominativ: ihre.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Nominative feminine: ihr + -e = ihre.', 'Nominativ feminin: ihr + -e = ihre.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6e623ea2-493e-53f9-9bbd-39d9e39f6ca3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0ee85922-aed7-5009-849c-d53a6a94e691'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 4, 'fill_blank', 'Wir fahren mit ___ Auto zur Werkstatt. (unser)', 'We are driving to the garage in our car. mit + dative, neuter noun. Base form: unser.', NULL, 'unserem', '["unserem"]'::jsonb, 'mit takes the dative and Auto is neuter, so unser becomes unserem.', 'mit + Dativ. Auto ist neutrum: unserem.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative neuter ends in -em, just like dem.', 'Dativ neutrum: Endung -em, wie bei dem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0ee85922-aed7-5009-849c-d53a6a94e691'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2f85346e-51f0-569d-8525-9328c1220ee4'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 4, 'fill_blank', 'Ich fahre oft mit ___ Kolleginnen. (mein)', 'I often travel with my (female) colleagues. mit + dative, plural noun. Base form: mein.', NULL, 'meinen', '["meinen"]'::jsonb, 'mit takes the dative and Kolleginnen is plural, so the ending is -en.', 'mit + Dativ, Plural: meinen Kolleginnen.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative plural: -en on the possessive, like den Kolleginnen.', 'Dativ Plural: -en, wie bei den Kolleginnen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2f85346e-51f0-569d-8525-9328c1220ee4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b4efc3ef-138a-54f6-9a1f-6d9bad0982ee'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 4, 'fill_blank', 'Wo sind ___ Koffer? (euer)', 'Where are your suitcases? Speaking to several friends, plural noun, nominative. Base form: euer.', NULL, 'eure', '["eure"]'::jsonb, 'Plural nominative needs -e, and euer loses the e in the middle: eure.', 'Plural Nominativ: euer wird eure.', 'Ein e fällt weg.', 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'euer + -e = eure, never euere.', 'euer + -e = eure, nie euere.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b4efc3ef-138a-54f6-9a1f-6d9bad0982ee'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c3ff3180-bb18-5d74-b38d-b2b09a460162'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'fill_blank', 'Wie geht es ___ Frau, Herr Berger? (Ihr)', 'How is your wife, Mr Berger? Polite Ihr, feminine noun, dative after es geht.', NULL, 'Ihrer', '["Ihrer"]'::jsonb, 'es geht takes a dative, and Frau is feminine, so the ending is -er.', 'es geht + Dativ. Frau ist feminin: Ihrer.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative feminine takes -er, like der Frau.', 'Dativ feminin: -er, wie bei der Frau.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c3ff3180-bb18-5d74-b38d-b2b09a460162'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e1a683c6-07f0-52e4-a644-0a8edcc82cff'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'fill_blank', 'Sie spielt am Nachmittag mit ___ Kindern. (ihr)', 'She plays with her children in the afternoon. mit + dative, plural noun. Base form: ihr.', NULL, 'ihren', '["ihren"]'::jsonb, 'mit takes the dative and Kindern is plural, so ihr becomes ihren.', 'mit + Dativ, Plural: ihren Kindern.', NULL, 14, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative plural: -en on the possessive and -n on the noun.', 'Dativ Plural: -en beim Possessivpronomen, -n beim Nomen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e1a683c6-07f0-52e4-a644-0a8edcc82cff'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b0cadf32-900e-591e-8fb9-7d0e00b2aa45'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / helfen / unser / Lehrerin]', 'Write the sentence: We help our teacher. helfen takes the dative; feminine noun. Start with ''Wir''.', NULL, 'Wir helfen unserer Lehrerin.', '["Wir helfen unserer Lehrerin.","Wir helfen unserer Lehrerin","Unserer Lehrerin helfen wir.","Unserer Lehrerin helfen wir"]'::jsonb, 'helfen is a dative verb, so Lehrerin stands in the dative: unserer Lehrerin.', 'helfen braucht den Dativ: unserer Lehrerin.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative verb + feminine noun = -er.', 'Dativ-Verb + feminin: Endung -er.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b0cadf32-900e-591e-8fb9-7d0e00b2aa45'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ca730166-3bb9-54f4-b611-407343d2c69c'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / suchen / mein / Wörterbuch]', 'Write the sentence: I am looking for my dictionary. Accusative object, neuter noun. Start with ''Ich''.', NULL, 'Ich suche mein Wörterbuch.', '["Ich suche mein Wörterbuch.","Ich suche mein Wörterbuch","Mein Wörterbuch suche ich.","Mein Wörterbuch suche ich"]'::jsonb, 'Wörterbuch is neuter, and neuter looks the same in the nominative and the accusative.', 'Wörterbuch ist neutrum. Nominativ und Akkusativ sind gleich.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Neuter accusative takes no ending: mein Wörterbuch, like ein Wörterbuch.', 'Neutrum Akkusativ ohne Endung: mein Wörterbuch.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ca730166-3bb9-54f4-b611-407343d2c69c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '72c06925-6683-53dc-94b1-73c7fa64cb0a'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / fahren / mit / sein / Fahrrad]', 'Write the sentence: He goes by his bike. mit + dative, neuter noun, and fahren becomes fährt. Start with ''Er''.', NULL, 'Er fährt mit seinem Fahrrad.', '["Er fährt mit seinem Fahrrad.","Er fährt mit seinem Fahrrad","Mit seinem Fahrrad fährt er.","Mit seinem Fahrrad fährt er"]'::jsonb, 'fahren has a vowel change in the er-form, and mit forces the dative: seinem Fahrrad.', 'fahren: er fährt. mit + Dativ: seinem Fahrrad.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Two steps: er fährt, and mit + Dativ neutrum gives -em.', 'Zwei Schritte: er fährt und mit + Dativ neutrum.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '72c06925-6683-53dc-94b1-73c7fa64cb0a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ba7409e1-0c15-5846-9f03-e5686268acf2'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wo / sein / euer / Kalender]', 'Write the sentence: Where is your calendar? Speaking to several friends, masculine noun, nominative. Start with ''Wo''.', NULL, 'Wo ist euer Kalender?', '["Wo ist euer Kalender?","Wo ist euer Kalender"]'::jsonb, 'Masculine nominative takes no ending, so euer stays exactly as it is.', 'Maskulin Nominativ ohne Endung: euer Kalender.', 'Ohne Endung bleibt euer gleich.', 18, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'No ending, no e falls out: euer Kalender, but eure Kalender in the plural.', 'Ohne Endung bleibt euer gleich: euer Kalender.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ba7409e1-0c15-5846-9f03-e5686268acf2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3a8e1bf5-23af-516e-9db9-d3241082f651'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wir wohnen bei unseren Tante."', 'Find the error and write the sentence correctly: "Wir wohnen bei unseren Tante." (bei + dative, feminine noun)', NULL, 'Wir wohnen bei unserer Tante.', '["Wir wohnen bei unserer Tante.","Wir wohnen bei unserer Tante"]'::jsonb, 'Tante is feminine singular, so the dative ending is -er, not the plural -en.', 'Tante ist feminin. Im Dativ heißt es unserer, nicht unseren.', NULL, 19, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative feminine = -er (der Tante); -en belongs to the plural.', 'Dativ feminin: -er wie bei der Tante. -en ist Plural.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3a8e1bf5-23af-516e-9db9-d3241082f651'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bb935802-9fef-5cca-ad48-774e2e119d6c'::uuid, '0cb350c6-6a2e-4dd7-8f98-bd89922163fc'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Ich schicke meiner Bruder ein Paket."', 'Find the error and write the sentence correctly: "Ich schicke meiner Bruder ein Paket." (dative object, masculine noun)', NULL, 'Ich schicke meinem Bruder ein Paket.', '["Ich schicke meinem Bruder ein Paket.","Ich schicke meinem Bruder ein Paket"]'::jsonb, 'Bruder is masculine, so the dative ending is -em; -er would be feminine.', 'Bruder ist maskulin. Im Dativ heißt es meinem.', NULL, 20, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Dative masculine = -em (dem Bruder), dative feminine = -er (der Schwester).', 'Dativ maskulin: -em. Dativ feminin: -er.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bb935802-9fef-5cca-ad48-774e2e119d6c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f6c88bd7-f85b-574b-9a11-84e9a4c02f99'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 4, 'fill_blank', 'Ich ___ am Wochenende mein Zimmer auf. (aufräumen, ich)', 'I tidy my room at the weekend. Type the conjugated verb for ''ich''; the prefix auf already stands at the end.', NULL, 'räume', '["räume"]'::jsonb, 'In a main clause the prefix auf goes to the end, and you conjugate only räumen.', 'Im Hauptsatz geht das Präfix auf ans Ende. Du konjugierst nur räumen.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'aufräumen splits: ich räume … auf. The stem takes the ich ending -e.', 'Bei aufräumen steht auf am Ende: ich räume … auf. Der Stamm bekommt -e.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f6c88bd7-f85b-574b-9a11-84e9a4c02f99'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '65196e96-fc16-563f-9615-51560b7a1d85'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 4, 'fill_blank', 'Ich hole meine Tochter um vier Uhr ___. (abholen)', 'I pick my daughter up at four o''clock. Type the separated prefix at the end of the sentence.', NULL, 'ab', '["ab"]'::jsonb, 'abholen splits in a main clause; the prefix ab stands at the very end.', 'abholen ist trennbar. Im Hauptsatz steht das Präfix ab ganz am Ende.', NULL, 17, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich hole … ab. The prefix always closes the main clause.', 'Ich hole … ab. Das Präfix geht immer ans Satzende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '65196e96-fc16-563f-9615-51560b7a1d85'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f22cfc5f-44ea-5699-996f-6a4327f1ba38'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 4, 'fill_blank', 'Wir ___ am Samstag mit Freunden aus. (ausgehen, wir)', 'We go out with friends on Saturday. Type the conjugated verb for ''wir''; the prefix aus already stands at the end.', NULL, 'gehen', '["gehen"]'::jsonb, 'You conjugate only the base verb gehen; the prefix aus stays at the end.', 'Du konjugierst nur das Grundverb gehen. Das Präfix aus bleibt am Ende.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ausgehen splits: wir gehen … aus. The wir form of gehen is gehen.', 'Bei ausgehen steht aus am Ende: wir gehen … aus. Die wir-Form ist gehen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f22cfc5f-44ea-5699-996f-6a4327f1ba38'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0ae0428a-6cb4-5d76-85ec-620eca762cb0'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 4, 'fill_blank', 'Kannst du bitte das Fenster ___? (aufmachen, mit Modalverb)', 'Can you please open the window? Type the verb form used after a modal verb.', NULL, 'aufmachen', '["aufmachen"]'::jsonb, 'After a modal verb the separable verb stays together in the infinitive at the end.', 'Nach einem Modalverb bleibt das Verb im Infinitiv am Ende zusammen.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'With können the prefix stays on the verb: Kannst du … aufmachen?', 'Mit können bleibt das Verb zusammen: Kannst du … aufmachen?', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0ae0428a-6cb4-5d76-85ec-620eca762cb0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3fc71876-317a-5bf2-a2b2-9e68d98b1a2a'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'sentence_building', 'Schreib den Satz: [am Freitag / ich / einladen / meine Freunde]', 'Write the sentence: On Friday I invite my friends. Start with ''Am Freitag'', so the verb comes second.', NULL, 'Am Freitag lade ich meine Freunde ein.', '["Am Freitag lade ich meine Freunde ein.","Am Freitag lade ich meine Freunde ein"]'::jsonb, 'The time phrase takes position one, the conjugated verb position two, and the prefix ein goes last.', 'Die Zeitangabe steht auf Position eins, das Verb auf Position zwei. Das Präfix ein steht am Ende.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Am Freitag lade ich … ein: inversion plus the separated prefix at the end.', 'Am Freitag lade ich … ein: Inversion und das Präfix am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3fc71876-317a-5bf2-a2b2-9e68d98b1a2a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bd4fc906-aa7f-5eca-94f0-574a1fd2d1e6'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / mitnehmen / der Regenschirm]', 'Write the sentence: He takes the umbrella with him. Start with ''Er''; nehmen changes its vowel in the er form.', NULL, 'Er nimmt den Regenschirm mit.', '["Er nimmt den Regenschirm mit.","Er nimmt den Regenschirm mit"]'::jsonb, 'mitnehmen splits, and the stem nehmen changes e to i in the er/sie/es form.', 'Bei mitnehmen steht mit am Ende. Der Stamm nehmen ändert e zu i bei er/sie/es.', 'nehmen: er nimmt.', 21, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Er nimmt … mit: vowel change, accusative den Regenschirm, prefix mit at the end.', 'Er nimmt … mit: Vokalwechsel, Akkusativ den Regenschirm, Präfix mit am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bd4fc906-aa7f-5eca-94f0-574a1fd2d1e6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e5258fe7-ec08-559c-9f41-6d0ed12c77ce'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du / müssen / dein Pass / mitbringen]', 'Write the sentence: You have to bring your passport. Start with ''Du''; after a modal verb the separable verb stays whole.', NULL, 'Du musst deinen Pass mitbringen.', '["Du musst deinen Pass mitbringen.","Du musst deinen Pass mitbringen"]'::jsonb, 'The modal verb stands in position two; mitbringen stays whole at the end.', 'Das Modalverb steht auf Position zwei. mitbringen bleibt am Ende ganz.', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dein Pass is the accusative object: deinen Pass. The infinitive mitbringen closes the sentence.', 'dein Pass ist das Akkusativobjekt: deinen Pass. Der Infinitiv mitbringen steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e5258fe7-ec08-559c-9f41-6d0ed12c77ce'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '26ef0497-431e-56e3-9dc2-f75363ba9e45'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'sentence_building', 'Schreib den Satz im Perfekt: [gestern / ich / einkaufen]', 'Write the sentence in the perfect tense: Yesterday I did the shopping. Start with ''Gestern''; einkaufen takes haben.', NULL, 'Gestern habe ich eingekauft.', '["Gestern habe ich eingekauft.","Gestern habe ich eingekauft"]'::jsonb, 'In the participle of a separable verb ge- sits between the prefix and the stem: eingekauft.', 'Im Partizip steht ge- zwischen Präfix und Stamm: eingekauft.', 'ein + ge + kauft.', 23, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Gestern habe ich eingekauft: haben in position two, the participle at the end.', 'Gestern habe ich eingekauft: haben auf Position zwei, das Partizip am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '26ef0497-431e-56e3-9dc2-f75363ba9e45'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b695989e-8d63-5c8b-9ec0-bcedcae726fb'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'error_correction', 'Korrigiere die Frage: „Wann kommt zurück dein Bruder?“', 'Correct the question: the separated prefix is in the wrong place. Write the whole question.', NULL, 'Wann kommt dein Bruder zurück?', '["Wann kommt dein Bruder zurück?","Wann kommt dein Bruder zurück"]'::jsonb, 'The prefix zurück belongs at the very end of the question.', 'Das Präfix zurück gehört ganz ans Ende der Frage.', NULL, 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wann kommt dein Bruder zurück? The prefix always closes the sentence bracket.', 'Wann kommt dein Bruder zurück? Das Präfix schließt immer die Satzklammer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b695989e-8d63-5c8b-9ec0-bcedcae726fb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '97b278f2-10c3-5506-b968-e9215c7fa5b5'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Das Konzert hat um acht Uhr angefangt.“', 'Correct the sentence: the participle of anfangen is irregular. Write the whole sentence.', NULL, 'Das Konzert hat um acht Uhr angefangen.', '["Das Konzert hat um acht Uhr angefangen.","Das Konzert hat um acht Uhr angefangen"]'::jsonb, 'anfangen has an irregular participle, so it ends in -en: angefangen.', 'Das Partizip von anfangen ist unregelmäßig. Es endet auf -en: angefangen.', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'an + ge + fangen = angefangen, not angefangt.', 'an + ge + fangen = angefangen, nicht angefangt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '97b278f2-10c3-5506-b968-e9215c7fa5b5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a01124d0-8bb6-56a9-8c4c-fb99cf4e139f'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Meine Freundin ist gestern spät ankommen.“', 'Correct the sentence: the participle of ankommen is missing its ge-. Write the whole sentence.', NULL, 'Meine Freundin ist gestern spät angekommen.', '["Meine Freundin ist gestern spät angekommen.","Meine Freundin ist gestern spät angekommen"]'::jsonb, 'In the participle of a separable verb ge- stands between the prefix and the stem.', 'Im Partizip steht ge- zwischen Präfix und Stamm.', 'an + ge + kommen.', 26, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'an + ge + kommen = angekommen. ankommen takes sein in the perfect tense.', 'an + ge + kommen = angekommen. ankommen bildet das Perfekt mit sein.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a01124d0-8bb6-56a9-8c4c-fb99cf4e139f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0f1ad5a9-fdc9-53db-a090-ea03b8ba5c4c'::uuid, '039d15ad-c3d1-4af8-bc89-c4ee0592dd02'::uuid, 5, 'error_correction', 'Korrigiere den Satz: „Ruf bitte an deine Schwester.“', 'Correct the imperative: the separated prefix must come last. Write the whole sentence.', NULL, 'Ruf bitte deine Schwester an.', '["Ruf bitte deine Schwester an.","Ruf bitte deine Schwester an!","Ruf bitte deine Schwester an","Rufe bitte deine Schwester an.","Rufe bitte deine Schwester an!","Rufe bitte deine Schwester an","Bitte ruf deine Schwester an.","Bitte ruf deine Schwester an!","Bitte ruf deine Schwester an","Bitte rufe deine Schwester an.","Bitte rufe deine Schwester an!","Bitte rufe deine Schwester an"]'::jsonb, 'In the imperative the verb comes first and the prefix an goes to the end.', 'Im Imperativ steht das Verb zuerst, das Präfix an am Ende.', NULL, 27, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ruf bitte deine Schwester an: object first, separated prefix last.', 'Ruf bitte deine Schwester an: zuerst das Objekt, am Ende das Präfix.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0f1ad5a9-fdc9-53db-a090-ea03b8ba5c4c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fe199e67-f51a-56fe-a831-21e35a2bc687'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 4, 'fill_blank', 'Ich habe am Samstag im Supermarkt ___. (einkaufen)', 'I did the shopping at the supermarket on Saturday. Separable verb einkaufen - write the participle.', NULL, 'eingekauft', '["eingekauft"]'::jsonb, 'einkaufen is stressed on ein-, so it is separable and the ge- sits in the middle.', 'einkaufen ist trennbar: ein + ge + kauft.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Separable verb: ein-ge-kauft, one word at the end of the sentence.', 'Trennbar: ein-ge-kauft, ein Wort am Satzende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fe199e67-f51a-56fe-a831-21e35a2bc687'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2765e704-0357-5a48-81c4-637525f08b53'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 4, 'fill_blank', 'Das Handy hat nicht ___. (funktionieren)', 'The phone did not work. Verb in -ieren - write the participle.', NULL, 'funktioniert', '["funktioniert"]'::jsonb, 'Verbs in -ieren build the participle with -t and never take ge-.', 'Bei -ieren steht kein ge-, nur ein -t.', 'Kein ge- bei -ieren.', 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'funktionieren -> funktioniert, like reservieren -> reserviert.', 'funktionieren wird funktioniert, wie reservieren wird reserviert.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2765e704-0357-5a48-81c4-637525f08b53'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '577622c9-faf8-5750-98bc-17629962dbff'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 4, 'fill_blank', 'Sie hat ihren Onkel ___. (besuchen)', 'She visited her uncle. Unstressed prefix be- - write the participle.', NULL, 'besucht', '["besucht"]'::jsonb, 'be- carries no stress, so it takes the place of the ge-.', 'be- steht ohne Betonung und ersetzt das ge-.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'besuchen -> besucht, like bezahlen -> bezahlt.', 'besuchen wird besucht, wie bezahlen wird bezahlt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '577622c9-faf8-5750-98bc-17629962dbff'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bc871bba-0741-5de8-9de6-2ab834d79e71'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 4, 'fill_blank', 'Ich habe meinem Lehrer einen Brief ___. (schreiben)', 'I wrote my teacher a letter. Irregular verb schreiben - write the participle.', NULL, 'geschrieben', '["geschrieben"]'::jsonb, 'schreiben is irregular: the participle ends in -en and the vowel changes.', 'schreiben ist unregelmäßig: geschrieben mit -en.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Irregular participles end in -en: geschrieben, gefunden, gesehen.', 'Diese Partizipien enden auf -en: geschrieben, gefunden.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bc871bba-0741-5de8-9de6-2ab834d79e71'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6ddb0a23-23ef-598a-9175-ba359790567b'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'fill_blank', 'Gestern ___ meine Nachbarin gekocht.', 'Yesterday my neighbour cooked. Fill in the correct form of haben (3rd person singular).', NULL, 'hat', '["hat"]'::jsonb, 'The time phrase takes position 1, so hat stays in position 2, before the subject.', 'Die Zeit steht auf Position 1, hat auf Position 2.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Time first means inversion: Gestern hat meine Nachbarin gekocht.', 'Zeit zuerst: Gestern hat meine Nachbarin gekocht.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6ddb0a23-23ef-598a-9175-ba359790567b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '95404dfc-7e59-5d16-8b6b-ae368f6d0347'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'fill_blank', '___ ihr am Sonntag Kuchen gebacken?', 'Did you bake a cake on Sunday? Speaking to several friends - fill in the correct form of haben.', NULL, 'Habt', '["Habt","habt"]'::jsonb, 'In a yes/no question the ihr-form of haben opens the sentence.', 'In der Ja/Nein-Frage steht habt ganz vorne.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr + haben = habt, in position 1 of a yes/no question.', 'ihr + haben = habt. In der Ja/Nein-Frage ganz vorne.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '95404dfc-7e59-5d16-8b6b-ae368f6d0347'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '17babe0d-ae68-5d9a-866d-70064d088192'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'fill_blank', 'Er hat sein Wörterbuch nicht ___. (finden)', 'He did not find his dictionary. Irregular verb finden - write the participle.', NULL, 'gefunden', '["gefunden"]'::jsonb, 'finden is irregular: gefunden. nicht stands in front of the participle.', 'finden ist unregelmäßig: gefunden. nicht steht vor dem Partizip.', NULL, 15, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The participle stays the last word, even with nicht in the sentence.', 'Auch mit nicht steht das Partizip ganz hinten.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '17babe0d-ae68-5d9a-866d-70064d088192'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '796f1b19-208b-5b13-8fc6-b185b5cbd3ea'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / haben / gestern / im Garten / arbeiten]', 'Write the sentence: I worked in the garden yesterday. Perfekt with haben. Start with ''Ich''.', NULL, 'Ich habe gestern im Garten gearbeitet.', '["Ich habe gestern im Garten gearbeitet.","Ich habe gestern im Garten gearbeitet","Gestern habe ich im Garten gearbeitet.","Gestern habe ich im Garten gearbeitet"]'::jsonb, 'habe takes position 2 and the participle gearbeitet closes the sentence.', 'habe steht auf Position 2, gearbeitet am Ende.', NULL, 16, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'arbeiten is regular but needs an extra -e-: ge-arbeit-et.', 'arbeiten ist regelmäßig, braucht aber ein -e-: gearbeitet.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '796f1b19-208b-5b13-8fc6-b185b5cbd3ea'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '88fc0611-159e-569e-9fa9-f30265b8616a'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wann / haben / du / das Paket / abholen]', 'Write the sentence: When did you collect the parcel? A W-question in the Perfekt. Start with ''Wann''.', NULL, 'Wann hast du das Paket abgeholt?', '["Wann hast du das Paket abgeholt?","Wann hast du das Paket abgeholt"]'::jsonb, 'The question word is first, hast is second and abgeholt closes the bracket.', 'Das W-Wort steht vorne, hast auf Position 2, abgeholt am Ende.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'abholen is stressed on ab-, so the ge- goes into the middle: ab-ge-holt.', 'abholen ist trennbar: ab-ge-holt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '88fc0611-159e-569e-9fa9-f30265b8616a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '94ca7dc1-61cc-5ddc-b564-126f1420e558'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / haben / unsere Kollegen / einladen]', 'Write the sentence: We invited our colleagues. Separable verb einladen. Start with ''Wir''.', NULL, 'Wir haben unsere Kollegen eingeladen.', '["Wir haben unsere Kollegen eingeladen.","Wir haben unsere Kollegen eingeladen"]'::jsonb, 'einladen is separable, so the participle is eingeladen and it closes the sentence.', 'einladen ist trennbar: das Partizip heißt eingeladen.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Object between the brackets, participle at the end.', 'Objekt in der Mitte, Partizip am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '94ca7dc1-61cc-5ddc-b564-126f1420e558'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ebfb87d9-c040-59f5-985a-c07f470cf592'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wir haben einen Tisch gereserviert."', 'Find the error and write the sentence correctly: "Wir haben einen Tisch gereserviert." (verb in -ieren)', NULL, 'Wir haben einen Tisch reserviert.', '["Wir haben einen Tisch reserviert.","Wir haben einen Tisch reserviert"]'::jsonb, 'reservieren ends in -ieren, so the participle is reserviert, with no ge-.', 'reservieren endet auf -ieren. Das Partizip heißt reserviert.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'No -ieren verb ever takes ge-.', 'Endung -ieren heißt: Partizip ohne ge-.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ebfb87d9-c040-59f5-985a-c07f470cf592'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7923782b-e2f9-53b7-ba2b-3933d18e65ed'::uuid, '70348f1d-4f6f-47d1-9c9f-6ce6b2117648'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Habt ihr gesehen die Fotos?"', 'Find the error and write the sentence correctly: "Habt ihr gesehen die Fotos?" (word order in the Satzklammer)', NULL, 'Habt ihr die Fotos gesehen?', '["Habt ihr die Fotos gesehen?","Habt ihr die Fotos gesehen"]'::jsonb, 'The participle has to be the last word, so the object moves in front of it.', 'Das Partizip steht am Ende. Das Objekt kommt davor.', NULL, 20, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Bracket: Habt … gesehen. Everything else sits inside it.', 'Klammer: Habt … gesehen. Alles andere steht dazwischen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7923782b-e2f9-53b7-ba2b-3933d18e65ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f4e936d3-7429-5717-9f5f-0ccf643ebe70'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 4, 'fill_blank', 'Am Sonntag sind wir nach Bremen ___. (fahren)', 'On Sunday we drove to Bremen. Movement verb fahren - write the participle.', NULL, 'gefahren', '["gefahren"]'::jsonb, 'fahren is irregular and shows movement, so the Perfekt is sind + gefahren.', 'fahren ist unregelmäßig und zeigt Bewegung: sind gefahren.', NULL, 16, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Movement from A to B always takes sein, and this participle ends in -en.', 'Bewegung von A nach B: immer sein. Partizip auf -en.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f4e936d3-7429-5717-9f5f-0ccf643ebe70'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '84fae3a3-546f-5195-a4e8-a96a7a28bae4'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 4, 'fill_blank', 'Meine Kinder sind heute früh ___. (aufstehen)', 'My children got up early today. Separable movement verb aufstehen - write the participle.', NULL, 'aufgestanden', '["aufgestanden"]'::jsonb, 'aufstehen is separable and takes sein, so the ge- sits in the middle.', 'aufstehen ist trennbar und nimmt sein: auf-ge-standen.', NULL, 17, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Separable verb with sein: auf-ge-standen, one word at the end.', 'Trennbar mit sein: auf-ge-standen, ein Wort am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '84fae3a3-546f-5195-a4e8-a96a7a28bae4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5b6f2e6f-f259-507d-9321-b186d9abbc79'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 4, 'fill_blank', 'Wir sind gestern spät ___. (zurückkommen)', 'We came back late yesterday. Separable movement verb zurückkommen - write the participle.', NULL, 'zurückgekommen', '["zurückgekommen"]'::jsonb, 'zurückkommen is separable, so the ge- sits between the prefix and the stem.', 'zurückkommen ist trennbar: zurück + ge + kommen.', NULL, 18, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Trennbar plus sein: zurück-ge-kommen, one word at the end.', 'Trennbar plus sein: zurück-ge-kommen, ein Wort am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5b6f2e6f-f259-507d-9321-b186d9abbc79'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2d4a626d-0cd0-57ee-9add-634bbd483cd7'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 4, 'fill_blank', 'Am Abend ist es kalt ___. (werden)', 'It got cold in the evening. Change-of-state verb werden - write the participle.', NULL, 'geworden', '["geworden"]'::jsonb, 'werden describes a change of state, so it takes sein; the participle is geworden.', 'werden zeigt eine Zustandsänderung und braucht sein: geworden.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Change of state means sein: es ist kalt geworden.', 'Zustandsänderung heißt sein: es ist kalt geworden.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2d4a626d-0cd0-57ee-9add-634bbd483cd7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3004cab5-8973-51f3-b3d2-e8cc65ec79dd'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'fill_blank', 'Meine Kollegen ___ mit dem Zug gekommen.', 'My colleagues came by train. Fill in the correct form of sein (plural).', NULL, 'sind', '["sind"]'::jsonb, 'kommen is a movement verb, and the plural form of sein is sind.', 'kommen zeigt Bewegung. Die Plural-Form von sein heißt sind.', NULL, 20, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Meine Kollegen is plural, so sind opens the bracket and gekommen closes it.', 'Meine Kollegen ist Plural: sind … gekommen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3004cab5-8973-51f3-b3d2-e8cc65ec79dd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '90e9c486-cc25-565b-9319-27963c5c1a79'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'fill_blank', 'Ich habe lange gearbeitet und ___ dann eingeschlafen.', 'I worked for a long time and then fell asleep. Fill in the correct auxiliary for einschlafen (ich-form).', NULL, 'bin', '["bin"]'::jsonb, 'arbeiten takes haben, but einschlafen is a change of state and takes sein.', 'arbeiten nimmt haben, einschlafen nimmt sein.', 'einschlafen ist eine Zustandsänderung.', 21, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Each verb keeps its own auxiliary, even inside one sentence.', 'Jedes Verb hat ein Hilfsverb, auch in einem Satz.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '90e9c486-cc25-565b-9319-27963c5c1a79'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a235c8d9-1d38-5afb-9f14-37ef548d1b70'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'fill_blank', 'Er hat bis acht Uhr im Büro ___. (arbeiten)', 'He worked in the office until eight. Verb with haben - write the participle.', NULL, 'gearbeitet', '["gearbeitet"]'::jsonb, 'arbeiten is an activity without movement, so it takes haben.', 'arbeiten ist eine Tätigkeit ohne Bewegung und nimmt haben.', NULL, 22, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'arbeiten is regular but adds an extra -e-: ge-arbeit-et.', 'arbeiten ist regelmäßig, braucht aber ein -e-: gearbeitet.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a235c8d9-1d38-5afb-9f14-37ef548d1b70'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e82dd094-e114-5c33-8328-249c6cb3b17d'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / sein / gestern / zum Zahnarzt / gehen]', 'Write the sentence: I went to the dentist yesterday. Perfekt with sein. Start with ''Ich''.', NULL, 'Ich bin gestern zum Zahnarzt gegangen.', '["Ich bin gestern zum Zahnarzt gegangen.","Ich bin gestern zum Zahnarzt gegangen","Gestern bin ich zum Zahnarzt gegangen.","Gestern bin ich zum Zahnarzt gegangen"]'::jsonb, 'gehen shows movement, so bin takes position 2 and gegangen closes the sentence.', 'gehen zeigt Bewegung: bin auf Position 2, gegangen am Ende.', NULL, 23, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'zu + dem becomes zum, and the participle stays the last word.', 'zu und dem wird zum. Das Partizip steht ganz hinten.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e82dd094-e114-5c33-8328-249c6cb3b17d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b13a96f0-7629-5666-b8d5-da0eb61de4a0'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / sein / um acht Uhr / ankommen]', 'Write the sentence: We arrived at eight o''clock. Separable verb ankommen with sein. Start with ''Wir''.', NULL, 'Wir sind um acht Uhr angekommen.', '["Wir sind um acht Uhr angekommen.","Wir sind um acht Uhr angekommen","Um acht Uhr sind wir angekommen.","Um acht Uhr sind wir angekommen"]'::jsonb, 'ankommen is separable and takes sein: an-ge-kommen becomes angekommen.', 'ankommen ist trennbar und nimmt sein: angekommen.', NULL, 24, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Perfekt the separable verb stays one word at the end.', 'Im Perfekt bleibt das Verb ein Wort am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b13a96f0-7629-5666-b8d5-da0eb61de4a0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3d2da8b8-806a-576d-9a31-cf94adbd2643'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wie lange / sein / ihr / in Wien / bleiben]', 'Write the sentence: How long did you stay in Vienna? A W-question in the Perfekt with sein. Start with ''Wie''.', NULL, 'Wie lange seid ihr in Wien geblieben?', '["Wie lange seid ihr in Wien geblieben?","Wie lange seid ihr in Wien geblieben"]'::jsonb, 'bleiben always takes sein, and the participle closes the bracket.', 'bleiben nimmt immer sein. Das Partizip schließt die Klammer.', NULL, 25, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr + sein = seid, in position 2 after the question phrase.', 'ihr plus sein ist seid, auf Position 2 nach dem W-Wort.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3d2da8b8-806a-576d-9a31-cf94adbd2643'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0c112fa4-b967-5ce6-85d7-62d0afe24872'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Die Kinder haben zum Bahnhof gelaufen."', 'Find the error and write the sentence correctly: "Die Kinder haben zum Bahnhof gelaufen." (auxiliary for a movement verb)', NULL, 'Die Kinder sind zum Bahnhof gelaufen.', '["Die Kinder sind zum Bahnhof gelaufen.","Die Kinder sind zum Bahnhof gelaufen"]'::jsonb, 'laufen with a destination is movement from A to B, so the auxiliary is sein.', 'laufen mit Ziel ist Bewegung von A nach B: sein.', NULL, 26, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ask wohin? If there is a destination, use sein.', 'Frag: wohin? Gibt es ein Ziel, dann sein.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0c112fa4-b967-5ce6-85d7-62d0afe24872'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0ba46f3e-387c-5f83-8205-96707b81a98e'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Wir sind das Museum besucht."', 'Find the error and write the sentence correctly: "Wir sind das Museum besucht." (auxiliary for a verb with an object)', NULL, 'Wir haben das Museum besucht.', '["Wir haben das Museum besucht.","Wir haben das Museum besucht"]'::jsonb, 'besuchen has an accusative object and no movement, so it takes haben.', 'besuchen hat ein Akkusativobjekt und keine Bewegung: haben.', NULL, 27, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'A verb with a direct object almost always takes haben.', 'Ein Verb mit Akkusativobjekt nimmt fast immer haben.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0ba46f3e-387c-5f83-8205-96707b81a98e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9ad5640e-466f-5386-842c-d8d94b063614'::uuid, 'cd09eecf-8121-4084-8eb6-264d2ed5d109'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Meine Eltern ist nach Italien geflogen."', 'Find the error and write the sentence correctly: "Meine Eltern ist nach Italien geflogen." (the auxiliary has to agree with the subject)', NULL, 'Meine Eltern sind nach Italien geflogen.', '["Meine Eltern sind nach Italien geflogen.","Meine Eltern sind nach Italien geflogen"]'::jsonb, 'The auxiliary agrees with the subject: Meine Eltern is plural, so it is sind.', 'Das Hilfsverb passt zum Subjekt. Meine Eltern ist Plural: sind.', NULL, 28, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'sein in the plural is sind, never ist.', 'sein im Plural heißt sind, nie ist.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9ad5640e-466f-5386-842c-d8d94b063614'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a1faf242-7d73-59ca-b22a-6c6ab9d238e5'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 4, 'fill_blank', '___ mir bitte den Kalender! (geben, du-Form)', 'Please give me the calendar. du-imperative of geben, which changes e to i.', NULL, 'Gib', '["Gib","gib"]'::jsonb, 'geben keeps the e to i change in the du-imperative: du gibst becomes Gib!', 'geben wechselt e zu i: du gibst, also Gib!', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'du-imperative = the du-form without -st: gibst becomes Gib.', 'du-Imperativ: gibst ohne -st ist Gib.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a1faf242-7d73-59ca-b22a-6c6ab9d238e5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9642339e-f4ee-5427-8342-b442e8d2d23f'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 4, 'fill_blank', '___ Sie bitte hier! (unterschreiben, Sie-Form)', 'Please sign here. Sie-imperative of unterschreiben.', NULL, 'Unterschreiben', '["Unterschreiben","unterschreiben"]'::jsonb, 'The Sie-form is the infinitive plus Sie, and unterschreiben stays in one piece.', 'Die Sie-Form ist der Infinitiv plus Sie. unter- ist nicht trennbar und bleibt am Verb.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'unterschreiben + Sie = Unterschreiben Sie! The prefix unter- is inseparable, so nothing moves to the end.', 'unterschreiben plus Sie: Unterschreiben Sie! Das Präfix unter- bleibt vorne.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9642339e-f4ee-5427-8342-b442e8d2d23f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'beaae871-40d5-5c83-b9f1-46cd0f6f248a'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 4, 'fill_blank', '___ heute Abend zu Hause, Kinder! (essen, ihr-Form)', 'Eat at home this evening, children. ihr-imperative of essen.', NULL, 'Esst', '["Esst","esst"]'::jsonb, 'The ihr-imperative looks exactly like the normal ihr-form, without the pronoun.', 'Der ihr-Imperativ ist die ihr-Form ohne ihr.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr esst becomes Esst! The e to i change belongs to du only.', 'Aus ihr esst wird Esst! Der Wechsel e zu i gilt nur für du.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'beaae871-40d5-5c83-b9f1-46cd0f6f248a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5ec6e5ba-f42a-5a64-877e-7815bd9c61a0'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 4, 'fill_blank', '___ bitte deinen Chef an! (anrufen, du-Form)', 'Please call your boss. du-imperative of the separable verb anrufen.', NULL, 'Ruf', '["Ruf","ruf","Rufe","rufe"]'::jsonb, 'anrufen is separable: only the stem Ruf opens the sentence, an stays at the end.', 'anrufen ist trennbar: Ruf steht vorne, an am Ende.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The prefix an is already at the end, so only Ruf is missing.', 'Das Präfix an steht schon am Ende. Vorne fehlt nur Ruf.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5ec6e5ba-f42a-5a64-877e-7815bd9c61a0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '71777d16-3fd2-5c3e-baf8-1146303a84c1'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'fill_blank', '___ mir bitte die Fotos! (zeigen, du-Form)', 'Please show me the photos. du-imperative of zeigen plus a dative pronoun.', NULL, 'Zeig', '["Zeig","zeig","Zeige","zeige"]'::jsonb, 'zeigen has no vowel change, so the du-imperative is simply the stem: Zeig!', 'zeigen hat keinen Vokalwechsel: Zeig!', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The dative pronoun mir comes directly after the verb.', 'Das Dativpronomen mir steht direkt nach dem Verb.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '71777d16-3fd2-5c3e-baf8-1146303a84c1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '485648bc-3987-5288-bf14-d7e6d325f54c'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'fill_blank', '___ Sie bitte Ihren Namen! (buchstabieren, Sie-Form)', 'Please spell your name. Sie-imperative of buchstabieren.', NULL, 'Buchstabieren', '["Buchstabieren","buchstabieren"]'::jsonb, 'The Sie-form is the infinitive plus Sie, however long the verb is - buchstabieren keeps every syllable.', 'Die Sie-Form ist immer der Infinitiv plus Sie.', NULL, 14, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'buchstabieren + Sie = Buchstabieren Sie! A useful phrase at any office counter.', 'buchstabieren plus Sie: Buchstabieren Sie! Das brauchst du oft im Amt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '485648bc-3987-5288-bf14-d7e6d325f54c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef829fd3-bc7d-586d-98d2-0214e21e9180'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'fill_blank', '___ bitte freundlich zu den Gästen! (sein, ihr-Form)', 'Please be friendly to the guests. ihr-imperative of the irregular verb sein.', NULL, 'Seid', '["Seid","seid"]'::jsonb, 'sein is irregular in every imperative form: Sei! Seid! Seien Sie!', 'sein ist unregelmäßig: Sei! Seid! Seien Sie!', NULL, 15, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ihr-form of sein is seid, and the imperative keeps it.', 'Die ihr-Form von sein ist seid. Der Imperativ bleibt gleich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef829fd3-bc7d-586d-98d2-0214e21e9180'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0b314f01-8055-554a-953a-930e5ef7ec1f'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'sentence_building', 'Schreib den Satz: [du-Form / aufstehen / bitte / um sieben Uhr]', 'Write the sentence: Please get up at seven o''clock. du-imperative of the separable verb aufstehen. Start with ''Steh''.', NULL, 'Steh bitte um sieben Uhr auf!', '["Steh bitte um sieben Uhr auf!","Steh bitte um sieben Uhr auf.","Steh bitte um sieben Uhr auf","Steh um sieben Uhr bitte auf!","Steh um sieben Uhr bitte auf.","Steh um sieben Uhr bitte auf"]'::jsonb, 'aufstehen splits: Steh opens the sentence and auf closes it.', 'aufstehen hat ein Präfix: Steh vorne, auf am Ende.', NULL, 16, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Nothing may stand after the prefix.', 'Nach dem Präfix steht nichts mehr.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0b314f01-8055-554a-953a-930e5ef7ec1f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e77ed643-7057-52c1-b012-48af04077f97'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'sentence_building', 'Schreib den Satz: [Sie-Form / anrufen / bitte / morgen]', 'Write the sentence: Please call tomorrow. Sie-imperative of the separable verb anrufen. Start with ''Rufen''.', NULL, 'Rufen Sie bitte morgen an!', '["Rufen Sie bitte morgen an!","Rufen Sie bitte morgen an.","Rufen Sie bitte morgen an","Rufen Sie morgen bitte an!","Rufen Sie morgen bitte an.","Rufen Sie morgen bitte an"]'::jsonb, 'Sie-imperative = infinitive + Sie, and the prefix an goes to the very end.', 'Sie-Imperativ: Infinitiv plus Sie. Das Präfix an steht am Ende.', NULL, 17, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sie always comes directly after the verb.', 'Sie steht immer direkt nach dem Verb.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e77ed643-7057-52c1-b012-48af04077f97'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8e7c6e70-d0be-552c-84eb-890a1734b033'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ihr-Form / anfangen / bitte / um acht Uhr]', 'Write the sentence: Please start at eight o''clock. ihr-imperative of the separable verb anfangen. Start with ''Fangt''.', NULL, 'Fangt bitte um acht Uhr an!', '["Fangt bitte um acht Uhr an!","Fangt bitte um acht Uhr an.","Fangt bitte um acht Uhr an","Fangt um acht Uhr bitte an!","Fangt um acht Uhr bitte an.","Fangt um acht Uhr bitte an"]'::jsonb, 'The ihr-imperative is Fangt, and the separable prefix an closes the sentence.', 'Der ihr-Imperativ heißt Fangt. Das Präfix an steht am Ende.', NULL, 18, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ihr-form has no vowel change: ihr fangt an.', 'Die ihr-Form hat keinen Vokalwechsel: ihr fangt an.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8e7c6e70-d0be-552c-84eb-890a1734b033'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f783bc6c-168f-5870-be37-b2e29fb68de9'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig: "Du komm bitte um acht!"', 'Find the error and write the sentence correctly: "Du komm bitte um acht!" (pronoun in the du-imperative)', NULL, 'Komm bitte um acht!', '["Komm bitte um acht!","Komm bitte um acht.","Komm bitte um acht"]'::jsonb, 'The du-imperative never keeps the pronoun du; only Sie stays.', 'Der du-Imperativ steht ohne du. Nur Sie bleibt stehen.', NULL, 19, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Komm! is already the command form, so du is not needed.', 'Komm! ist schon die Befehlsform. du ist nicht nötig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f783bc6c-168f-5870-be37-b2e29fb68de9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '460df823-fa58-53c2-8cd1-7f10be185da5'::uuid, '85bdc240-4015-4ce5-b94b-59c678550f8b'::uuid, 5, 'error_correction', 'Finde den Fehler und schreib den Satz richtig (Sie-Form): "Sei Sie bitte leise!"', 'Find the error and write the sentence correctly, keeping the Sie-form: "Sei Sie bitte leise!"', NULL, 'Seien Sie bitte leise!', '["Seien Sie bitte leise!","Seien Sie bitte leise.","Seien Sie bitte leise"]'::jsonb, 'sein has its own Sie-form: Seien Sie! Sei! belongs to du.', 'sein hat eine Sie-Form: Seien Sie! Sei! gehört zu du.', NULL, 20, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Three forms of sein: Sei! (du), Seid! (ihr), Seien Sie! (Sie).', 'Drei Formen von sein: Sei! Seid! Seien Sie!', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '460df823-fa58-53c2-8cd1-7f10be185da5'::uuid);


